INSERT INTO knowledge.chunks (id, tenant_id, document_id, version_id, ordinal, content, checksum) VALUES ('88d15d3a-2987-5191-a831-0780d55c04ce'::uuid, 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'::uuid, '049bd25e-78de-52f5-b295-df9c4a63c279'::uuid, 'eca68d62-dfaa-5334-84e0-aa2d22256a78'::uuid, 2, '## 控制指标

