INSERT INTO knowledge.chunks (id, tenant_id, document_id, version_id, ordinal, content, checksum) VALUES ('0b31631b-af7e-5a37-9fec-bd9d6ce8841e'::uuid, 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'::uuid, '08e61516-7a13-558c-b821-2fd5a0c375f1'::uuid, 'f3f71d36-6517-56cc-a821-28e75cd73577'::uuid, 2, '## 控制指标

