INSERT INTO knowledge.chunks (id, tenant_id, document_id, version_id, ordinal, content, checksum) VALUES ('df28516a-8cdc-540a-b2b2-4c79bfc01786'::uuid, 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'::uuid, '08e61516-7a13-558c-b821-2fd5a0c375f1'::uuid, 'f3f71d36-6517-56cc-a821-28e75cd73577'::uuid, 3, '## 记录与复核

