INSERT INTO knowledge.chunks (id, tenant_id, document_id, version_id, ordinal, content, checksum) VALUES ('35f04fe5-b914-570f-a8ff-c502f782197e'::uuid, 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'::uuid, '1bd2ee81-f52f-51ee-a1e3-9147447f3937'::uuid, '56d052e4-72b6-5851-b203-dc27c7f68561'::uuid, 2, '## 控制指标

