INSERT INTO knowledge.chunks (id, tenant_id, document_id, version_id, ordinal, content, checksum) VALUES ('6f4b0e61-12ca-5f3a-80ca-690920097ad4'::uuid, 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'::uuid, '24055ed9-9d54-52c3-a893-32ca36df4db7'::uuid, '8b6c6a8c-518d-5650-92f1-8df69b338a95'::uuid, 1, '## 职责与授权

