INSERT INTO knowledge.chunks (id, tenant_id, document_id, version_id, ordinal, content, checksum) VALUES ('e2936161-dd46-5cdd-8e01-df70f781a1b1'::uuid, 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'::uuid, '2f26e194-26a6-57d0-bb7f-ed374a71b595'::uuid, 'f868cd16-c708-5124-bf04-93e045455842'::uuid, 2, '## 控制指标

