INSERT INTO knowledge.chunks (id, tenant_id, document_id, version_id, ordinal, content, checksum) VALUES ('3a8d75f7-31c3-570b-aa4b-eb0fe88781aa'::uuid, 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'::uuid, '2f26e194-26a6-57d0-bb7f-ed374a71b595'::uuid, 'f868cd16-c708-5124-bf04-93e045455842'::uuid, 3, '## 记录与复核

