INSERT INTO knowledge.chunks (id, tenant_id, document_id, version_id, ordinal, content, checksum) VALUES ('a3d82cbe-d952-5680-be2c-17418da2bb85'::uuid, 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'::uuid, '40a1ec9c-09dd-5741-8bb5-59b55e0f802c'::uuid, 'b0909572-08db-5d13-b4b3-5d4a4e81c18f'::uuid, 1, '## 职责与授权

