INSERT INTO knowledge.chunks (id, tenant_id, document_id, version_id, ordinal, content, checksum) VALUES ('8914a210-1e44-5ffd-8f86-743b9ecad943'::uuid, 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'::uuid, '40a1ec9c-09dd-5741-8bb5-59b55e0f802c'::uuid, 'b0909572-08db-5d13-b4b3-5d4a4e81c18f'::uuid, 2, '## 控制指标

