INSERT INTO knowledge.chunks (id, tenant_id, document_id, version_id, ordinal, content, checksum) VALUES ('ff382e28-9a4e-57a2-87b5-b6c4c67d608e'::uuid, 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'::uuid, '41bbaa5b-777b-52ad-960e-81533b9a62cb'::uuid, '0e4716a4-d5eb-56e8-9c26-91b647ffeafe'::uuid, 4, '## 升级与例外

