INSERT INTO knowledge.chunks (id, tenant_id, document_id, version_id, ordinal, content, checksum) VALUES ('b4044a57-c6ea-532e-8a87-b7bcf1efd1b2'::uuid, 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'::uuid, '41bbaa5b-777b-52ad-960e-81533b9a62cb'::uuid, '51918344-22ef-5c2f-a538-38616d667c70'::uuid, 1, '## 职责与授权

