INSERT INTO knowledge.chunks (id, tenant_id, document_id, version_id, ordinal, content, checksum) VALUES ('a420d3cb-df32-51d9-af67-ee40b0a2cb22'::uuid, 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'::uuid, '5021a568-12fc-536d-8016-29b3d195e9d0'::uuid, 'e357385c-68a5-5922-8240-7981b5c88258'::uuid, 2, '## 控制指标

