INSERT INTO knowledge.chunks (id, tenant_id, document_id, version_id, ordinal, content, checksum) VALUES ('37510c52-3d9a-5afc-99e1-adc23ec03b20'::uuid, 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'::uuid, '63cb12a8-19fe-548d-8b33-110505f5b9d8'::uuid, '33e3cf49-905a-5e63-ae74-b8f85a69a8e1'::uuid, 3, '## 记录与复核

