INSERT INTO knowledge.chunks (id, tenant_id, document_id, version_id, ordinal, content, checksum) VALUES ('e9f0541a-bb3e-5d29-980a-24b90957348f'::uuid, 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'::uuid, '6c0de25d-0302-5c91-8abd-a63c1486ef11'::uuid, 'd9872a8b-e66d-5a3e-94ec-936867cdda81'::uuid, 4, '## 升级与例外

