INSERT INTO knowledge.chunks (id, tenant_id, document_id, version_id, ordinal, content, checksum) VALUES ('c13a8fcb-f2e1-506c-a4a6-ab3511317e9b'::uuid, 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'::uuid, '7c858977-0d44-5f8c-b4c8-2890f59a5b11'::uuid, 'f3cb1b89-f12e-5f74-9489-5a38c426ff72'::uuid, 3, '## 记录与复核

