INSERT INTO knowledge.chunks (id, tenant_id, document_id, version_id, ordinal, content, checksum) VALUES ('ca15031f-5b71-54ac-8521-993d23543eed'::uuid, 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'::uuid, '8346f871-8057-5768-afa1-18c22c69891e'::uuid, 'd18e9c67-d8f6-50fd-9ade-2445b13ec94e'::uuid, 2, '## 控制指标

