INSERT INTO knowledge.chunks (id, tenant_id, document_id, version_id, ordinal, content, checksum) VALUES ('01796472-49e5-52d7-93ba-86ecf09411a0'::uuid, 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'::uuid, '98171b02-3aaa-5231-bc10-5c87aa190f93'::uuid, '66046c3b-58e3-58c3-9762-358eea82c6fe'::uuid, 3, '## 记录与复核

