INSERT INTO knowledge.chunks (id, tenant_id, document_id, version_id, ordinal, content, checksum) VALUES ('967807a9-1ca6-5462-aecf-264a1837b810'::uuid, 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'::uuid, '9f7240f2-e905-5f9a-9ee9-d657e9da2201'::uuid, '524b584a-1320-55e3-9c85-f3373f2be28d'::uuid, 1, '## 职责与授权

