INSERT INTO knowledge.chunks (id, tenant_id, document_id, version_id, ordinal, content, checksum) VALUES ('029d43e1-c513-52d7-b70f-645a69b6acfd'::uuid, 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'::uuid, 'a1fcbf25-54ac-5525-ba33-658e99e77280'::uuid, '56c3e775-4a39-51ce-a5a1-c4d5cd5af187'::uuid, 2, '## 控制指标

