INSERT INTO knowledge.chunks (id, tenant_id, document_id, version_id, ordinal, content, checksum) VALUES ('d8d5d3c4-99f2-54bf-9564-0d46cbeeb3e6'::uuid, 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'::uuid, 'a3c0a5db-497d-5e2a-9a48-fad14a921544'::uuid, 'e22aa90d-8fae-574c-82fb-6b4dfd869522'::uuid, 1, '## 职责与授权

