INSERT INTO knowledge.chunks (id, tenant_id, document_id, version_id, ordinal, content, checksum) VALUES ('b19034e1-a1a4-5f28-9e72-b0138876f8cf'::uuid, 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'::uuid, 'a3c0a5db-497d-5e2a-9a48-fad14a921544'::uuid, 'e22aa90d-8fae-574c-82fb-6b4dfd869522'::uuid, 2, '## 控制指标

