INSERT INTO knowledge.chunks (id, tenant_id, document_id, version_id, ordinal, content, checksum) VALUES ('8a9c8c35-1534-58f6-b0d4-1606559f7d71'::uuid, 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'::uuid, 'aaebb19e-db89-5418-a52b-8778aaf3424f'::uuid, 'd4e4cb76-486e-5371-b387-507ad394a5d2'::uuid, 2, '## 控制指标

