INSERT INTO knowledge.chunks (id, tenant_id, document_id, version_id, ordinal, content, checksum) VALUES ('f454de0f-d140-5202-b71b-0de58bb32a39'::uuid, 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'::uuid, 'abfbcb9b-3366-5a36-9418-989e7dd67242'::uuid, '972f534e-631c-55f2-9b70-6a67effe6650'::uuid, 3, '## 记录与复核

