INSERT INTO knowledge.chunks (id, tenant_id, document_id, version_id, ordinal, content, checksum) VALUES ('8464e6a1-5ca1-5709-b01a-29ed2d3b6dc1'::uuid, 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'::uuid, 'ba28aac6-f492-570b-a636-c7497d640396'::uuid, 'de0457d4-b685-5ad6-952c-16230ffada85'::uuid, 2, '## 控制指标

