INSERT INTO knowledge.chunks (id, tenant_id, document_id, version_id, ordinal, content, checksum) VALUES ('8112c893-cc55-555a-a97e-c4e8e08fbe7f'::uuid, 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'::uuid, 'be7b0447-b271-540d-a550-5460afa8bf49'::uuid, 'e2dbcb81-9821-503a-90c3-ab9c30ef67b9'::uuid, 2, '## 控制指标

