INSERT INTO knowledge.chunks (id, tenant_id, document_id, version_id, ordinal, content, checksum) VALUES ('694d194c-3884-5197-8def-600473f02c0a'::uuid, 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'::uuid, 'd5de254a-482e-517c-859a-53849d870916'::uuid, '7116566c-22ad-50c4-a655-9d9eb1f85540'::uuid, 4, '## 升级与例外

